// Read-only — urgent findings only (exception-only paging, issue #658).
// Mirror: lib/server/ops-notification-policy.js shouldPageBusinessOpsFinding()
const body = $input.first().json;
const findings = Array.isArray(body.findings) ? body.findings : [];
const summary = body.summary && typeof body.summary === 'object' ? body.summary : {};
const page = findings.filter(f => f && f.severity === 'urgent' && !f.safeToIgnore);
const lines = page.slice(0, 8).map(f => [
  `[${String(f.severity).toUpperCase()}] ${f.objectType} ${f.objectRef}`,
  `Action: ${f.actionRequired}`,
  `Next: ${f.recommendedNextAction}`,
  f.link ? `Link: ${f.link}` : null,
].filter(Boolean).join('\n'));
return [{ json: {
  schema: body.schema,
  ok: body.ok,
  evaluated_at: body.evaluated_at,
  urgent_count: page.length,
  action_required: summary.actionRequired || 0,
  should_alert: page.length > 0,
  alert_text: page.length
    ? 'CorpFlowAI Business Ops — urgent action needed\n\n' + lines.join('\n\n---\n\n')
    : '',
  findings_page: page,
} }];
